        </div>
        <div className="flex items-center gap-4 w-full h-8">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right flex-shrink-0" style={labelStyle}>Ton</span>
             <div className="flex-1 min-w-0 flex items-center">
