import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
// Indices correspond to [3, 5, 7, 11, 13]
export const BASIS_VECTORS_X = [
    100, // Prime 3
    30,  // Prime 5
    20,  // Prime 7
    -20, // Prime 11
    -30  // Prime 13
];

const PRIMES = [3, 5, 7, 11, 13];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 * All layouts are designed to be relative to (0,0) as the 1/1 origin.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice',
    settings?: AppSettings
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 160; // Standard spacing for alternate layouts
    const p3 = coords[0] || 0;
    const p5 = coords[1] || 0;
    const p7 = coords[2] || 0;
    const p11 = coords[3] || 0;
    const p13 = coords[4] || 0;

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        y = -(Math.log2(ratio) * PITCH_SCALE);
    } 
    else if (approach === 'lattice2d' && settings) {
        // Map specific primes to X and Y axes
        const idxX = PRIMES.indexOf(settings.lattice2d_limitX || 11);
        const idxY = PRIMES.indexOf(settings.lattice2d_limitY || 3);
        const stepX = idxX !== -1 ? coords[idxX] : 0;
        const stepY = idxY !== -1 ? coords[idxY] : 0;
        x = stepX * spacing;
        y = -stepY * spacing;
    }
    else if (approach === 'diamond') {
        const unit = spacing * 0.7;
        x = (p3 - p5) * unit;
        y = (p3 + p5) * (unit * 0.5); 
        x += (p7 * 0.4 + p11 * -0.3) * unit;
        y += (p7 * 0.2 + p13 * 0.4) * unit;
        x = x * (1.0 / aspectRatio);
    }
    else if (approach === 'row') {
        x = Math.log2(ratio) * 1200; 
        const maxP = Math.max(1, ...coords.map((c, i) => c !== 0 ? [3,5,7,11,13][i] : 1));
        const limitIndex = [1, 3, 5, 7, 11, 13].indexOf(maxP);
        const dir = limitIndex % 2 === 0 ? 1 : -1;
        y = dir * (limitIndex * spacing * 0.5);
        y += (p3 * 4 + p5 * 2); 
    }
    else if (approach === 'honeycomb') {
        const hexUnit = spacing * 0.85;
        x = (p3 + p5 * 0.5 - p7 * 0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;
        x += (p11 * 0.3) * hexUnit;
        y += (p13 * 0.3) * hexUnit;
        x = x * (1.0 / aspectRatio);
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  while (b !== 0) {
    let t = b;
    b = a % b;
    a = t;
  }
  return a;
};

const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    this.n = n;
    this.d = d;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;

    const divisor = gcd(nn, dd);
    nn /= divisor;
    dd /= divisor;

    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;

    return new Fraction(nn, dd);
  }

  // Adjust fraction by octave shift
  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) {
        nn *= Math.pow(2, octave);
    } else if (octave < 0) {
        dd *= Math.pow(2, Math.abs(octave));
    }
    const divisor = gcd(nn, dd);
    return new Fraction(nn / divisor, dd / divisor);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

// --- Generation ---

export const getHarmonicDistance = (coordsA: number[], coordsB: number[] = [0,0,0,0,0]): number => {
  const p3 = coordsA[0] - coordsB[0];
  const p5 = coordsA[1] - coordsB[1];
  let hexDist = 0;
  if (Math.sign(p3) === Math.sign(p5) && p3 !== 0 && p5 !== 0) {
    hexDist = Math.abs(p3) + Math.abs(p5);
  } else {
    hexDist = Math.max(Math.abs(p3), Math.abs(p5));
  }
  let otherDist = 0;
  for (let i = 2; i < coordsA.length; i++) {
    otherDist += Math.abs(coordsA[i] - coordsB[i]);
  }
  return hexDist + otherDist;
};

const calculateRatioFromCoords = (coords: number[]): Fraction => {
    let ratio = new Fraction(1, 1);
    PRIMES.forEach((prime, idx) => {
        const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
        const val = coords[idx];
        if (val === 0) return;
        for(let i=0; i < Math.abs(val); i++) {
             if (val > 0) ratio = ratio.mul(pRat).normalize();
             else {
                 const invRatio = new Fraction(pRat.d, pRat.n);
                 ratio = ratio.mul(invRatio).normalize();
             }
        }
    });
    return ratio;
};

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}],
    existingNodesMap?: Map<string, LatticeNode>,
    startIndex: number = 0
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  const nodesMap: Map<string, LatticeNode> = existingNodesMap ? new Map(existingNodesMap) : new Map();
  const OCTAVE_RANGE = 2; 

  for (let i = startIndex; i < generationOrigins.length; i++) {
      const origin = generationOrigins[i];
      const localQueue: { coords: number[], ratio: Fraction, relativeRatio: Fraction }[] = [];
      const originFrac = calculateRatioFromCoords(origin.coords);
      const originKey = origin.coords.join(',');
      const visitedLocal = new Set<string>();

      localQueue.push({ coords: origin.coords, ratio: originFrac, relativeRatio: new Fraction(1, 1) });
      visitedLocal.add(originKey);

      const MAX_LOCAL_NODES = 1000;
      let processedCount = 0;
      const foundBaseNodes: { coords: number[], ratio: Fraction }[] = [];

      while (localQueue.length > 0 && processedCount < MAX_LOCAL_NODES) {
        const current = localQueue.shift()!;
        processedCount++;
        const { coords, ratio, relativeRatio } = current;

        if (settings.layoutApproach === 'lattice2d') {
            const pX = settings.lattice2d_limitX;
            const pY = settings.lattice2d_limitY;
            let invalid = false;
            PRIMES.forEach((p, idx) => {
                if (p !== pX && p !== pY && coords[idx] !== 0) invalid = true;
            });
            if (!invalid) foundBaseNodes.push({ coords, ratio });
        } else {
            foundBaseNodes.push({ coords, ratio });
        }

        PRIMES.forEach((prime, idx) => {
          const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
          if (depthLimit <= 0) return;
          if (settings.layoutApproach === 'lattice2d') {
             if (prime !== settings.lattice2d_limitX && prime !== settings.lattice2d_limitY) return;
          }
          const complexityLimit = settings.limitComplexities[prime as 3|5|7|11|13];
          [1, -1].forEach(dir => {
            const nextPos = [...coords];
            nextPos[idx] += dir;
            if (Math.abs(nextPos[idx] - origin.coords[idx]) > depthLimit) return;
            const posKey = nextPos.join(',');
            if (!visitedLocal.has(posKey)) {
                visitedLocal.add(posKey);
                 let nextRatio: Fraction;
                 let nextRelativeRatio: Fraction;
                 const pRat = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS];
                 if (dir === 1) {
                    nextRatio = ratio.mul(pRat).normalize();
                    nextRelativeRatio = relativeRatio.mul(pRat).normalize();
                 } else {
                    const invRatio = new Fraction(pRat.d, pRat.n);
                    nextRatio = ratio.mul(invRatio).normalize();
                    nextRelativeRatio = relativeRatio.mul(invRatio).normalize();
                 }
                 if (nextRelativeRatio.n <= complexityLimit && nextRelativeRatio.d <= complexityLimit) {
                    localQueue.push({ coords: nextPos, ratio: nextRatio, relativeRatio: nextRelativeRatio });
                 }
            }
          });
        });
      }

      foundBaseNodes.forEach(data => {
          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
               const shiftedRatio = data.ratio.shiftOctave(oct);
               const absoluteRatio = shiftedRatio.n / shiftedRatio.d;
               const coordKey = data.coords.join(',');
               const id = `${coordKey}:${oct}`;
               if (!nodesMap.has(id)) {
                   const limitTop = getMaxPrime(shiftedRatio.n);
                   const limitBottom = getMaxPrime(shiftedRatio.d);
                   const maxPrime = Math.max(limitTop, limitBottom);
                   const { x, y } = projectCoordinates(data.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach, settings);
                   nodesMap.set(id, { id, coords: data.coords, ratio: absoluteRatio, n: shiftedRatio.n, d: shiftedRatio.d, label: `${shiftedRatio.n}/${shiftedRatio.d}`, x, y, limitTop, limitBottom, maxPrime, octave: oct });
               }
          }
      });
  }

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];
  nodes.sort((a, b) => b.maxPrime - a.maxPrime);

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          if (settings.limitDepths[prime as 3|5|7|11|13] <= 0) return;
          if (settings.layoutApproach === 'lattice2d' && prime !== settings.lattice2d_limitX && prime !== settings.lattice2d_limitY) return;
          const neighborCoords = [...node.coords];
          neighborCoords[idx] += 1;
          const coordKey = neighborCoords.join(',');
          const basePrimeRatio = PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].n / PRIME_RATIOS[prime as keyof typeof PRIME_RATIOS].d;
          for(let o = node.octave - 1; o <= node.octave + 1; o++) {
              const targetId = `${coordKey}:${o}`;
              const target = nodesMap.get(targetId);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / basePrimeRatio;
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({ id: `${node.id}-${target.id}`, x1: node.x, y1: node.y, x2: target.x, y2: target.y, limit: prime, sourceId: node.id, targetId: target.id });
                  }
              }
          }
      });
      const octUpId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octUpNode = nodesMap.get(octUpId);
      if (octUpNode) {
          lines.push({ id: `${node.id}-oct-${node.octave}`, x1: node.x, y1: node.y, x2: octUpNode.x, y2: octUpNode.y, limit: 1, sourceId: node.id, targetId: octUpNode.id });
      }
  });

  return { nodes, lines };
};

