                         <button key={sys} onClick={() => handleChange('tuningSystem', sys)} className={`flex-1 px-3 py-2 text-[10px] font-bold rounded border transition-all uppercase tracking-widest ${settings.tuningSystem === sys ? 'bg-blue-600 border-blue-400 text-white shadow-lg' : 'bg-slate-700 border-slate-600 text-slate-400 hover:bg-slate-600'}`}>{sys}</button>
                     ))}
