                          <div className="bg-slate-900/40 p-4 rounded-lg border border-slate-700/50">
                            <label className="block text-[10px] text-slate-400 font-bold uppercase mb-2 tracking-widest">Tonality Font</label>
                            <select value={settings.tonalityFontFamily} onChange={(e) => handleChange('tonalityFontFamily', e.target.value)} className="w-full bg-slate-800 border border-slate-600 rounded p-2 text-sm text-white focus:outline-none focus:border-blue-500">
                              {FONTS.map(font => <option key={font.value} value={font.value} style={{ fontFamily: font.value }}>{font.label}</option>)}
                            </select>
                          </div>
                      </div>
                      <div className="space-y-6">
                          <h3 className="font-semibold text-blue-300 border-b border-slate-700 pb-1">Axis Depth Controls</h3>
                          <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-3">
                              {[3, 5, 7, 11, 13].map(limit => (
                                  <div key={limit} className="flex items-center gap-3">
                                      <span className="w-16 text-xs font-bold text-slate-400">{limit}-Limit</span>
                                      <input type="range" min="0" max="6" step="1" value={settings.limitDepths?.[limit as 3|5|7|11|13] ?? 0} onChange={(e) => handleLimitDepthChange(limit as any, parseInt(e.target.value))} className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500" />
                                      <span className="text-xs font-mono w-4 text-right text-blue-400">{settings.limitDepths?.[limit as 3|5|7|11|13] ?? 0}</span>
                                  </div>
                              ))}
                          </div>
                      </div>
                  </div>
              </div>
            )}

            {activeTab === 'behavior' && (
              <div className="space-y-8 animate-in fade-in duration-300">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Audio Performance</h3>
                    <div className="flex gap-2">
                        {['interactive', 'balanced', 'playback'].map(mode => (
                            <button key={mode} onClick={() => handleChange('audioLatencyHint', mode)} className={`flex-1 py-2 text-xs font-bold rounded border capitalize ${settings.audioLatencyHint === mode ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>{mode}</button>
                        ))}
                    </div>
                    <label className="flex items-center justify-between cursor-pointer">
                      <span className="text-sm font-semibold">Enable Keyboard Shortcuts</span>
                      <input type="checkbox" checked={settings.enableKeyboardShortcuts} onChange={(e) => handleChange('enableKeyboardShortcuts', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-indigo-500" />
                    </label>
                  </div>
                  <div className="space-y-6">
                    <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Key Bindings</h3>
                    <div className="space-y-2 max-h-80 overflow-y-auto pr-2">
                      {renderKeyBinding('Latch All', 'latch')}
                      {renderKeyBinding('Panic', 'panic')}
                      {renderKeyBinding('All Notes Off', 'off')}
                      {renderKeyBinding('Center View', 'center')}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'visuals' && (
              <div className="space-y-8 animate-in fade-in duration-300">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <h3 className="font-semibold text-pink-400 border-b border-slate-700 pb-1">Node Graphics</h3>
                    <div className="space-y-4">
                      <div>
                        <label className="block text-sm font-semibold mb-2">Button Shape</label>
                        <div className="flex gap-2">
                          <button onClick={() => handleChange('buttonShape', ButtonShape.CIRCLE)} className={`flex-1 py-2 text-xs font-bold rounded border ${settings.buttonShape === ButtonShape.CIRCLE ? 'bg-pink-600 border-pink-500' : 'bg-slate-700 border-slate-600'}`}>Circle</button>
                          <button onClick={() => handleChange('buttonShape', ButtonShape.DIAMOND)} className={`flex-1 py-2 text-xs font-bold rounded border ${settings.buttonShape === ButtonShape.DIAMOND ? 'bg-pink-600 border-pink-500' : 'bg-slate-700 border-slate-600'}`}>Diamond</button>
                          <button onClick={() => handleChange('buttonShape', ButtonShape.SQUARE)} className={`flex-1 py-2 text-xs font-bold rounded border ${settings.buttonShape === ButtonShape.SQUARE ? 'bg-pink-600 border-pink-500' : 'bg-slate-700 border-slate-600'}`}>Square</button>
                        </div>
                      </div>
                      <div className="space-y-2">
                        <label className="block text-sm font-semibold">Button Size Scale</label>
                        <input type="range" min="0.5" max="2.0" step="0.1" value={settings.buttonSizeScale} onChange={(e) => handleChange('buttonSizeScale', parseFloat(e.target.value))} className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
  globalScale?: number; 
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean; 
}

const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * globalScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map(audioLatchedNodes);
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              visual.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];
    if (reach === 1) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) active.push(line);
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();
      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);
          if (sActive || tActive) {
              resultLines.add(line);
              if (sActive) step1Neighbors.add(line.targetId);
              if (tActive) step1Neighbors.add(line.sourceId);
          }
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);
  const globalScaleRef = useRef(globalScale);
  const persistentLatchesRef = useRef(persistentLatches);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
        }
    },
    decreaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        audioLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  const generationDeps = useMemo(() => {
      return JSON.stringify({
          tuning: settings.tuningSystem,
          layout: settings.layoutApproach,
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          skin: settings.activeSkin,
          l2dX: settings.lattice2d_limitX,
          l2dY: settings.lattice2d_limitY
      });
  }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin, settings.lattice2d_limitX, settings.lattice2d_limitY]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            if (effectiveSettings.limitDepths[limit as 3|5|7|11|13] !== undefined) effectiveSettings.limitDepths[limit as 3|5|7|11|13] = 0;
        });
        const result = generateLattice(effectiveSettings);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });
        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }
        const padding = 800; 
        const spacing = settingsRef.current.buttonSpacingScale * globalScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
        const clampedSize = Math.min(finalSize, 5000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;
      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
      const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);
      const size = dynamicSize;
      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);
      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
      const isSquare = settings.buttonShape === ButtonShape.SQUARE;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice';

      for (const line of data.lines) {
          const color = isJIOverride ? 'rgba(255,255,255,0.4)' : (settings.colors[line.limit] || '#666');
          ctx.beginPath();
          ctx.moveTo(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset);
          ctx.lineTo(line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
          ctx.lineWidth = (line.limit === 1 ? 2 : 1) * globalScale; 
          ctx.strokeStyle = color;
          ctx.globalAlpha = (isJIOverride ? 0.2 : 0.3);
          if (line.limit === 1) ctx.setLineDash([8 * globalScale, 8 * globalScale]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const radius = baseRadius * topVis.size;
          ctx.globalAlpha = topVis.opacity;
          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius); ctx.lineTo(x + radius, y); ctx.lineTo(x, y + radius); ctx.lineTo(x - radius, y);
          } else if (isSquare) {
              ctx.rect(x - radius, y - radius, radius * 2, radius * 2);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();
          if (isJIOverride) {
              ctx.fillStyle = 'rgba(20, 20, 20, 0.9)'; ctx.fill();
              ctx.lineWidth = 1.5 * globalScale; ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)'; ctx.stroke();
          } else {
              const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
              grad.addColorStop(0.45, settings.colors[node.limitTop] || '#666');
              grad.addColorStop(0.55, settings.colors[node.limitBottom] || '#666');
              ctx.fillStyle = grad; ctx.fill();
          }
          const combinedScale = settings.buttonSizeScale * topVis.size;
          if (combinedScale > 0.35) {
              ctx.fillStyle = isJIOverride ? '#fff' : 'white';
              ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
              let fontSize = Math.max(9, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * globalScale;
              ctx.font = `bold ${fontSize}px ${settings.tonalityFontFamily}`; 
              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
              if (settings.showFractionBar) {
                  ctx.beginPath(); ctx.moveTo(x - (radius * 0.4), y); ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1 * globalScale; ctx.strokeStyle = isJIOverride ? 'rgba(255,255,255,0.4)' : 'rgba(255,255,255,0.8)'; ctx.stroke();
              }
              ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
          }
      }
  }, [data, dynamicSize, settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.buttonShape, settings.tonalityFontFamily]); 

  const findNodeAtPos = (x: number, y: number) => {
    const spacing = settingsRef.current.buttonSpacingScale * globalScaleRef.current;
    const centerOffset = dynamicSizeRef.current / 2;
    const radius = (60 * settingsRef.current.buttonSizeScale * globalScaleRef.current) / 2 * 1.4;
    const col = Math.floor(x / GRID_CELL_SIZE);
    const row = Math.floor(y / GRID_CELL_SIZE);
    for (let c = col - 1; c <= col + 1; c++) {
      for (let r = row - 1; r <= row + 1; r++) {
        const nodes = spatialGridRef.current.get(`${c},${r}`);
        if (nodes) {
          for (const node of nodes) {
            const nx = node.x * spacing + centerOffset;
            const ny = node.y * spacing + centerOffset;
            if ((x - nx) ** 2 + (y - ny) ** 2 < radius * radius) return node;
          }
        }
      }
    }
    return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    const container = scrollContainerRef.current;
    if (!container) return;
    const rect = container.getBoundingClientRect();
    const x = (e.clientX - rect.left) + container.scrollLeft;
    const y = (e.clientY - rect.top) + container.scrollTop;
    const node = findNodeAtPos(x, y);
    const pointerId = e.pointerId;
    e.currentTarget.setPointerCapture(pointerId);
    if (node) {
      const voiceId = `${pointerId}-${node.id}`;
      audioEngine.startVoice(voiceId, node.ratio, settingsRef.current.baseFrequency);
      onNodeTrigger?.(node.id, node.ratio, node.n, node.d, node.maxPrime);
      lastTouchedLimitRef.current = node.maxPrime;
      onLimitInteraction(node.maxPrime);
      setActiveCursors(prev => {
        const next = new Map(prev);
        next.set(pointerId, { pointerId, currentX: x, currentY: y, originNodeId: node.id, hoverNodeId: node.id, hasMoved: false });
        return next;
      });
      if (latchMode === 1) setPersistentLatches(prev => new Map(prev).set(node.id, node.id));
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    const cursor = activeCursors.get(e.pointerId);
    if (!cursor) return;
    const container = scrollContainerRef.current;
    if (!container) return;
    const rect = container.getBoundingClientRect();
    const x = (e.clientX - rect.left) + container.scrollLeft;
    const y = (e.clientY - rect.top) + container.scrollTop;
    const node = findNodeAtPos(x, y);
    const moved = Math.abs(x - cursor.currentX) > 5 || Math.abs(y - cursor.currentY) > 5;
    if (settingsRef.current.isPitchBendEnabled && cursor.originNodeId) {
        const originNode = nodeMapRef.current.get(cursor.originNodeId);
        if (originNode) {
            const spacing = settingsRef.current.buttonSpacingScale * globalScaleRef.current;
            const deltaY = y - (originNode.y * spacing + dynamicSizeRef.current / 2);
            const ratio = originNode.ratio * getPitchRatioFromScreenDelta(deltaY, spacing);
            audioEngine.glideVoice(`${e.pointerId}-${cursor.originNodeId}`, ratio, settingsRef.current.baseFrequency);
        }
    }
    setActiveCursors(prev => new Map(prev).set(e.pointerId, { ...cursor, currentX: x, currentY: y, hoverNodeId: node ? node.id : null, hasMoved: cursor.hasMoved || moved }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    const cursor = activeCursors.get(e.pointerId);
    if (cursor && cursor.originNodeId) {
        const voiceId = `${e.pointerId}-${cursor.originNodeId}`;
        if (latchMode === 0) audioEngine.stopVoice(voiceId);
        else if (latchMode === 2) setPersistentLatches(prev => new Map(prev).set(cursor.originNodeId!, cursor.originNodeId!));
    }
    setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
  };

  const render = (time: number) => {
      const activeCanvas = dynamicCanvasRef.current;
      if (!activeCanvas) { animationFrameRef.current = requestAnimationFrame(render); return; }
      const activeCtx = activeCanvas.getContext('2d', { alpha: true });
      if (!activeCtx) return; 
      const currentSettings = settingsRef.current;
      const size = dynamicSizeRef.current;
      const isJIOverride = currentSettings.tuningSystem === 'ji' && currentSettings.layoutApproach !== 'lattice';
      const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
      const isSquare = currentSettings.buttonShape === ButtonShape.SQUARE;
      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
      const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);
      if (activeCanvas.width !== size * dpr || activeCanvas.height !== size * dpr) {
            activeCanvas.width = size * dpr; activeCanvas.height = size * dpr; activeCtx.scale(dpr, dpr);
      }
      let viewX = 0, viewY = 0, viewW = size, viewH = size;
      if (scrollContainerRef.current) {
          viewX = scrollContainerRef.current.scrollLeft; viewY = scrollContainerRef.current.scrollTop;
          viewW = scrollContainerRef.current.clientWidth; viewH = scrollContainerRef.current.clientHeight;
      }
      activeCtx.clearRect(viewX, viewY, viewW, viewH);
      const centerOffset = size / 2;
      const spacing = currentSettings.buttonSpacingScale * globalScaleRef.current;
      const baseRadius = (60 * currentSettings.buttonSizeScale * globalScaleRef.current) / 2;

      for (const id of visualLatchedRef.current.keys()) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;
             const x = node.x * spacing + centerOffset; const y = node.y * spacing + centerOffset;
             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
             const radius = baseRadius * vis.size * currentSettings.latchedZoomScale;
             activeCtx.beginPath();
             if (isDiamond) { activeCtx.moveTo(x, y - radius); activeCtx.lineTo(x + radius, y); activeCtx.lineTo(x, y + radius); activeCtx.lineTo(x - radius, y); }
             else if (isSquare) { activeCtx.rect(x - radius, y - radius, radius * 2, radius * 2); }
             else { activeCtx.arc(x, y, radius, 0, Math.PI * 2); }
             activeCtx.fillStyle = isJIOverride ? '#fff' : (currentSettings.colors[node.limitTop] || '#666');
             activeCtx.fill();
             activeCtx.lineWidth = isJIOverride ? 4 : 2; activeCtx.strokeStyle = '#fff'; activeCtx.stroke();
      }
      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => { animationFrameRef.current = requestAnimationFrame(render); return () => cancelAnimationFrame(animationFrameRef.current); }, []); 

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
        <div className="relative" style={{ width: dynamicSize, height: dynamicSize, backgroundColor: '#000' }}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
// Indices correspond to [3, 5, 7, 11, 13]
export const BASIS_VECTORS_X = [
    100, // Prime 3
    30,  // Prime 5
    20,  // Prime 7
    -20, // Prime 11
    -30  // Prime 13
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 * All layouts are designed to be relative to (0,0) as the 1/1 origin.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 160; 
    const p3 = coords[0] || 0;
    const p5 = coords[1] || 0;
    const p7 = coords[2] || 0;
    const p11 = coords[3] || 0;
    const p13 = coords[4] || 0;

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        // y is 0 when ratio is 1.0
        y = -(Math.log2(ratio) * PITCH_SCALE);
    } 
    else if (approach === 'diamond') {
        // Center-aligned Diamond: Prime 3 and 5 as primary diagonals
        const unit = spacing * 0.75;
        x = (p3 - p5) * unit;
        y = (p3 + p5) * (unit * 0.5); 

        // Secondary prime offsets
        x += (p7 * 0.4 + p11 * -0.3) * unit;
        y += (p7 * 0.2 + p13 * 0.4) * unit;

        x = x * (1.0 / aspectRatio);
    }
    else if (approach === 'row') {
        // Horizontal Strip: X = Log Frequency (Cents), Y = Harmonic Complexity
        x = Math.log2(ratio) * 1200; 

        const maxP = Math.max(1, ...coords.map((c, i) => c !== 0 ? [3,5,7,11,13][i] : 1));
        const limitIndex = [1, 3, 5, 7, 11, 13].indexOf(maxP);

        const dir = limitIndex % 2 === 0 ? 1 : -1;
        y = dir * (limitIndex * spacing * 0.4);

        // Prevent total overlap on identical cents
        y += (p3 * 6 + p5 * 3); 
    }
    else if (approach === 'honeycomb') {
        const hexUnit = spacing * 0.8;
        x = (p3 + p5 * 0.5 - p7 * 0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;

        x += (p11 * 0.3) * hexUnit;
        y += (p13 * 0.3) * hexUnit;

        x = x * (1.0 / aspectRatio);
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
  globalScale?: number; 
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean; 
}

const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * globalScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map(audioLatchedNodes);
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              visual.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;

    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                active.push(line);
            }
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
          }
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);
  const globalScaleRef = useRef(globalScale);
  const persistentLatchesRef = useRef(persistentLatches);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useEffect(() => {
      const handleBlur = () => {
          if (activeCursorsRef.current.size > 0) {
              setActiveCursors(new Map());
              cursorPositionsRef.current.clear();
              audioEngine.stopAll();
              midiService.panic();
          }
      };
      window.addEventListener('blur', handleBlur);
      return () => window.removeEventListener('blur', handleBlur);
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        audioLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSizeRef.current / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  const generationDeps = useMemo(() => {
      return JSON.stringify({
          tuning: settings.tuningSystem,
          layout: settings.layoutApproach,
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          skin: settings.activeSkin
      });
  }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const result = generateLattice(settings);
        const hiddenLimits = settings.hiddenLimits || [];
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const spacing = settingsRef.current.buttonSpacingScale * globalScale; 
        const calculatedSize = (maxExtent * spacing * 2) + 800;
        const clampedSize = Math.min(Math.max(calculatedSize, 2000), 5000);

        setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;

      canvas.width = size * dpr;
      canvas.height = size * dpr;
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;

      // Render Vibrant Background Lines
      for (const line of data.lines) {
          const visualSettings = settings.limitVisuals?.[line.limit] || { size: 1, opacity: 1 };
          const color = settings.colors[line.limit] || '#666';

          ctx.beginPath();
          ctx.moveTo(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset);
          ctx.lineTo(line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
          ctx.lineWidth = (line.limit === 1 ? 2 : 1) * visualSettings.size * globalScale;
          ctx.strokeStyle = color;
          ctx.globalAlpha = 0.4 * visualSettings.opacity;

          if (line.limit === 1) ctx.setLineDash([8 * globalScale, 8 * globalScale]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }

      // Render Radiant Vibrant Nodes
      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const radius = baseRadius * topVis.size;

          ctx.globalAlpha = topVis.opacity;

          // Glow Aura
          const glow = ctx.createRadialGradient(x, y, 0, x, y, radius * 2);
          glow.addColorStop(0, settings.colors[node.limitTop] + '66');
          glow.addColorStop(1, 'transparent');
          ctx.fillStyle = glow;
          ctx.beginPath();
          ctx.arc(x, y, radius * 2, 0, Math.PI * 2);
          ctx.fill();

          ctx.beginPath();
          if (settings.buttonShape === ButtonShape.DIAMOND) {
              ctx.moveTo(x, y - radius); ctx.lineTo(x + radius, y); ctx.lineTo(x, y + radius); ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0, settings.colors[node.limitTop] || '#666');
          grad.addColorStop(1, settings.colors[node.limitBottom] || '#333');
          ctx.fillStyle = grad;
          ctx.fill();

          ctx.lineWidth = 1 * globalScale;
          ctx.strokeStyle = 'rgba(255,255,255,0.3)';
          ctx.stroke();

          if (settings.buttonSizeScale * topVis.size > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
              let fontSize = Math.max(9, Math.min(18, 14 * settings.buttonSizeScale * topVis.size)) * settings.nodeTextSizeScale * globalScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
              if (settings.showFractionBar) {
                  ctx.beginPath(); ctx.moveTo(x - (radius * 0.4), y); ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1 * globalScale; ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.stroke();
              }
              ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
          }
      }
  }, [data, dynamicSize, settings.colors, settings.buttonSizeScale, settings.buttonSpacingScale, settings.limitVisuals, settings.buttonShape, settings.showFractionBar, settings.nodeTextSizeScale, globalScale]);

  const render = (time: number) => {
      const activeCanvas = dynamicCanvasRef.current;
      if (!activeCanvas) { animationFrameRef.current = requestAnimationFrame(render); return; }
      const ctx = activeCanvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const currentSettings = settingsRef.current;
      const size = dynamicSizeRef.current;
      const spacing = currentSettings.buttonSpacingScale * globalScaleRef.current;
      const centerOffset = size / 2;
      const baseRadius = (60 * currentSettings.buttonSizeScale * globalScaleRef.current) / 2;

      ctx.clearRect(0, 0, size, size);

      // Render Latched/Active Nodes with Pulse and High-Saturation Glows
      for (const id of visualLatchedRef.current.keys()) {
          const node = nodeMapRef.current.get(id);
          if (!node) continue;

          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
          const radius = baseRadius * vis.size * currentSettings.latchedZoomScale;

          const pulse = 1.0 + Math.sin(time * 0.01) * 0.05;
          const activeColor = currentSettings.colors[node.limitTop] || '#fff';

          ctx.shadowBlur = 20 * globalScaleRef.current;
          ctx.shadowColor = activeColor;

          ctx.beginPath();
          ctx.arc(x, y, radius * pulse, 0, Math.PI * 2);
          ctx.fillStyle = activeColor;
          ctx.fill();

          ctx.shadowBlur = 0;
          ctx.lineWidth = 4 * globalScaleRef.current;
          ctx.strokeStyle = 'white';
          ctx.stroke();
      }

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();
      const x = (clientX - rect.left) + scrollContainerRef.current.scrollLeft;
      const y = (clientY - rect.top) + scrollContainerRef.current.scrollTop;

      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settingsRef.current.buttonSpacingScale * globalScaleRef.current;
      const baseRadius = (60 * settingsRef.current.buttonSizeScale * globalScaleRef.current) / 2;

      for (const node of dataRef.current.nodes) {
          const nx = node.x * spacing + centerOffset;
          const ny = node.y * spacing + centerOffset;
          const vis = settingsRef.current.limitVisuals?.[node.limitTop] || { size: 1 };
          const r = baseRadius * vis.size;
          if (Math.abs(x - nx) < r && Math.abs(y - ny) < r) return node;
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      const node = getHitNode(e.clientX, e.clientY);
      if (node) {
          onLimitInteraction(node.maxPrime);
          lastTouchedLimitRef.current = node.maxPrime;
          const voiceId = `pointer-${e.pointerId}-${node.id}`;
          audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, latchMode === 2 ? 'latch' : 'normal');
          if (latchMode === 1) setPersistentLatches(prev => new Map(prev).set(node.id, node.id));

          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, { pointerId: e.pointerId, currentX: e.clientX, currentY: e.clientY, originNodeId: node.id, hoverNodeId: node.id, hasMoved: false });
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      const cursor = activeCursors.get(e.pointerId);
      if (cursor && cursor.originNodeId && latchMode === 0) {
          audioEngine.stopVoice(`pointer-${e.pointerId}-${cursor.originNodeId}`);
      }
      setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
  };

  const getBackgroundStyle = () => {
      const base: React.CSSProperties = { width: dynamicSize, height: dynamicSize, position: 'relative', backgroundColor: '#020617' };
      if (settings.backgroundMode === 'rainbow') {
          const period = getRainbowPeriod(settings.buttonSpacingScale * globalScale);
          base.backgroundImage = `linear-gradient(to bottom, #1e1b4b, #312e81, #1e1b4b)`;
          base.backgroundSize = `100% ${period}px`;
      }
      return base;
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerUp={handlePointerUp}>
        <div style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 pointer-events-none" />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 pointer-events-none" />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 pointer-events-none" />
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);
